// The front ends to check: Live and Building apps with a URL.
const reg = $('Read Registry').first().json.body || [];
const urls = [...new Set(reg
  .filter(a => (a.lifecycle === 'Live' || a.lifecycle === 'Building') && a.front_end_url)
  .map(a => a.front_end_url))];
return urls.length ? urls.map(url => ({ json: { url } })) : [{ json: { url: null } }];

// The Supabase projects to check: haggerty-marketing, HCI Inventory and
// 3-week-Lookahead today, read from app_registry.supabase_ref.
const reg = $('Read Registry').first().json.body || [];
const refs = [...new Set(reg
  .filter(a => (a.lifecycle === 'Live' || a.lifecycle === 'Building') && a.supabase_ref)
  .map(a => a.supabase_ref))];
return refs.length ? refs.map(ref => ({ json: { ref } })) : [{ json: { ref: null } }];

// Works out green / amber / red for every app and signal, from what the
// read-only checks before this one found. Nothing here writes anywhere.
const N8N = 'https://haggertybuilds.app.n8n.cloud';
const SB = 'https://supabase.com/dashboard/project/';
const DAY = 24 * 3600 * 1000;
const now = Date.now();
const errText = j => {
  if (!j) return 'no response';
  const e = j.error;
  if (!e) return 'no response';
  return String(typeof e === 'string' ? e : (e.message || e.description || JSON.stringify(e))).slice(0, 200);
};

const reg = $('Read Registry').first().json.body || [];
const checked = a => a.lifecycle === 'Live' || a.lifecycle === 'Building';
const results = [];
const push = (app, signal, status, detail, link, meta) =>
  results.push({ app, signal, status, detail, link: link || null, meta: meta || {} });

// ---- Site: a 200 is green, anything else is red.
const sites = $('List Sites').all().map(i => i.json);
const answers = $('Check Site').all().map(i => i.json);
const siteBy = {};
sites.forEach((s, i) => { if (s.url) siteBy[s.url] = answers[i] || {}; });
for (const a of reg.filter(a => checked(a) && a.front_end_url)) {
  const r = siteBy[a.front_end_url] || {};
  const code = r.statusCode;
  if (code === 200) push(a.app, 'site', 'green', 'Site up (200).', a.front_end_url, { code });
  else if (code) push(a.app, 'site', 'red', 'Site returned ' + code + '.', a.front_end_url, { code });
  else push(a.app, 'site', 'red', 'Site did not answer: ' + errText(r), a.front_end_url, {});
}

// ---- Supabase: project status, then security advisor findings that are
// not in the saved baseline. New WARN = amber, new ERROR = red.
const refs = $('List Projects').all().map(i => i.json.ref);
const stat = $('Project Status').all().map(i => i.json);
const adv = $('Security Advisors').all().map(i => i.json);
const base = $('Read Baselines').first().json.body || [];
const known = new Set(base.map(b => b.supabase_ref + '|' + b.cache_key));
const hasBase = new Set(base.map(b => b.supabase_ref));
const baseline_add = [];
const sb = {};
refs.forEach((ref, i) => {
  if (!ref) return;
  const p = stat[i] || {};
  const lints = (adv[i] || {}).lints;
  const advLink = SB + ref + '/advisors/security';
  if (p.error || !p.status) { sb[ref] = { status: 'amber', detail: 'Could not read the project status: ' + errText(p), link: SB + ref }; return; }
  if (p.status !== 'ACTIVE_HEALTHY') { sb[ref] = { status: 'red', detail: 'Project ' + (p.name || ref) + ' is ' + p.status + '.', link: SB + ref }; return; }
  if (!Array.isArray(lints)) { sb[ref] = { status: 'amber', detail: 'Project healthy, but the security advisor could not be read: ' + errText(adv[i]), link: advLink }; return; }
  // One entry per finding. The API gives a cache_key per finding; if it
  // ever groups them under findings[], key each by its name and object.
  const issues = lints.flatMap(x => Array.isArray(x.findings)
      ? x.findings.map(f => ({ name: x.name, level: x.level, title: x.title, detail: f.detail, metadata: f.metadata }))
      : [x])
    .filter(x => x.level === 'WARN' || x.level === 'ERROR')
    .map(x => Object.assign({}, x, { cache_key: x.cache_key || (x.name + ':' + JSON.stringify(x.metadata || x.detail || '')) }));
  if (!hasBase.has(ref)) {
    issues.forEach(x => baseline_add.push({ ref, cache_key: x.cache_key, name: x.name, level: x.level }));
    sb[ref] = { status: 'green', detail: 'Healthy. Baseline saved: ' + issues.length + ' known advisor warnings.', link: advLink, meta: { known: issues.length, new: [] } };
    return;
  }
  const fresh = issues.filter(x => !known.has(ref + '|' + x.cache_key));
  const knownCount = issues.length - fresh.length;
  if (!fresh.length) {
    sb[ref] = { status: 'green', detail: 'Healthy. No new advisor warnings (' + knownCount + ' known).', link: advLink, meta: { known: knownCount, new: [] } };
    return;
  }
  const isErr = fresh.some(x => x.level === 'ERROR');
  const byName = {};
  fresh.forEach(x => { byName[x.name] = (byName[x.name] || 0) + 1; });
  const list = Object.entries(byName).map(([n, c]) => n + (c > 1 ? ' x' + c : '')).join(', ');
  sb[ref] = {
    status: isErr ? 'red' : 'amber',
    detail: 'Healthy, but ' + fresh.length + ' new security advisor ' + (isErr ? 'finding' : 'warning') + (fresh.length > 1 ? 's' : '') + ': ' + list + '.',
    link: advLink,
    meta: { known: knownCount, new: fresh.slice(0, 20).map(x => ({ name: x.name, level: x.level, title: x.title, detail: String(x.detail || '').slice(0, 300) })) }
  };
});
for (const a of reg.filter(a => checked(a) && a.supabase_ref)) {
  const s = sb[a.supabase_ref];
  if (s) push(a.app, 'supabase', s.status, s.detail, s.link, Object.assign({ ref: a.supabase_ref }, s.meta || {}));
}

// ---- n8n: failed runs in the last 24 hours, matched to apps by name.
// 0 = green, 1-3 = amber, more than 3 or failing every run = red.
const wfs = $('n8n Workflows').all().flatMap(i => i.json.data || []);
const exs = $('n8n Executions').all().flatMap(i => i.json.data || [])
  .filter(e => new Date(e.startedAt).getTime() >= now - DAY);
const byName = {};
wfs.forEach(w => { (byName[w.name] = byName[w.name] || []).push(w); });
const stats = {};
for (const e of exs) {
  const s = stats[e.workflowId] = stats[e.workflowId] || { fail: 0, ok: 0, lastFail: '', lastFailId: null };
  if (e.status === 'error' || e.status === 'crashed') {
    s.fail++;
    if (String(e.startedAt) > s.lastFail) { s.lastFail = String(e.startedAt); s.lastFailId = e.id; }
  } else if (e.status === 'success') s.ok++;
}
const alerts = $('Recent Alert Messages').first().json.body || [];
const alertBy = {};
for (const a of alerts) if (!alertBy[a.workflow_id]) alertBy[a.workflow_id] = a;

const mapped = new Set();
reg.forEach(a => (a.workflow_names || []).forEach(n => (byName[n] || []).forEach(w => mapped.add(w.id))));

const failingOf = ws => ws.map(w => {
  const s = stats[w.id];
  if (!s || !s.fail) return null;
  const al = alertBy[w.id] || {};
  return {
    id: w.id, name: w.name, active: !!w.active, fail: s.fail, ok: s.ok, runs: s.fail + s.ok,
    every: s.fail >= 2 && s.ok === 0, last_failed_at: s.lastFail || null, execution: s.lastFailId,
    node: al.node_name || null, message: al.message ? String(al.message).slice(0, 400) : null
  };
}).filter(Boolean).sort((x, y) => y.fail - x.fail);

const describe = f => f.name + ' failed ' + f.fail + ' of ' + f.runs + ' run' + (f.runs === 1 ? '' : 's') + ' in 24h'
  + (f.node ? ' at ' + f.node : '') + (f.message ? ': ' + f.message.slice(0, 160) : '');
const failLink = f => N8N + '/workflow/' + f.id + '/executions' + (f.execution ? '/' + f.execution : '');

function n8nSignal(app, ws, missing, extra) {
  const failing = failingOf(ws);
  const total = failing.reduce((t, f) => t + f.fail, 0);
  const ran = ws.filter(w => stats[w.id]).length;
  const meta = Object.assign({ failing, missing, workflows: ws.length, ran }, extra || {});
  let status = 'green', detail = '', link = N8N + '/home/workflows';
  if (failing.length) {
    status = (total > 3 || failing.some(f => f.every)) ? 'red' : 'amber';
    detail = describe(failing[0]) + (failing.length > 1 ? '. Also: ' + failing.slice(1).map(f => f.name + ' (' + f.fail + ')').join(', ') : '') + '.';
    link = failLink(failing[0]);
  } else {
    detail = 'No failed runs in 24h across ' + ws.length + ' workflow' + (ws.length === 1 ? '' : 's') + ' (' + ran + ' ran).';
  }
  if (missing.length) {
    if (status === 'green') { status = 'amber'; detail = ''; }
    detail += (detail ? ' ' : '') + 'Not found in n8n (renamed?): ' + missing.join(', ') + '.';
  }
  if (extra && extra.unlisted && extra.unlisted.length) {
    if (status === 'green') { status = 'amber'; detail = ''; }
    detail += (detail ? ' ' : '') + extra.unlisted.length + ' active workflow' + (extra.unlisted.length === 1 ? ' is' : 's are') + ' not listed under any app: ' + extra.unlisted.slice(0, 6).join(', ') + (extra.unlisted.length > 6 ? ', ...' : '') + '.';
  }
  push(app, 'n8n', status, detail, link, meta);
}

for (const a of reg) {
  if (a.lifecycle === 'Retired' || a.app === 'Other n8n workflows') continue;
  const names = a.workflow_names || [];
  if (!names.length) continue;
  const ws = names.flatMap(n => byName[n] || []);
  const missing = names.filter(n => !byName[n]);
  n8nSignal(a.app, ws, missing);
}
// Anything not listed under an app lands here, so nothing slips through.
const others = wfs.filter(w => !mapped.has(w.id));
if (reg.some(a => a.app === 'Other n8n workflows')) {
  n8nSignal('Other n8n workflows', others, [], { unlisted: others.filter(w => w.active).map(w => w.name) });
}

return [{ json: { run_at: new Date(now).toISOString(), results, baseline_add } }];

// One email listing every app that just turned red. Apps that were
// already red last hour are not in the list, so this stays quiet.
const red = $json.newly_red || [];
const esc = v => String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rows = red.map(r =>
  '<div style="border-left:3px solid #A6402C;padding:6px 0 6px 14px;margin:0 0 14px;">'
  + '<div style="font-size:16px;font-weight:bold;color:#1C1B1A;">' + esc(r.app) + '</div>'
  + '<div style="font-size:13.5px;color:#1C1B1A;white-space:pre-wrap;margin-top:4px;">' + esc(r.detail) + '</div>'
  + (r.link ? '<div style="margin-top:6px;font-size:13px;"><a href="' + esc(r.link) + '" style="color:#F68922;font-weight:bold;">Open it</a></div>' : '')
  + '</div>').join('');
const html = '<div style="font-family:Arial,Helvetica,sans-serif;max-width:620px;">'
  + '<div style="font-size:12px;letter-spacing:.1em;text-transform:uppercase;color:#A6402C;font-weight:bold;margin-bottom:12px;">'
  + (red.length === 1 ? 'An app turned red' : red.length + ' apps turned red') + '</div>'
  + rows
  + '<p style="margin-top:18px;font-size:14px;"><a href="https://haggertybuilds.github.io/Marketing-Lead-and-Email-Application/#health" style="color:#F68922;font-weight:bold;">Open the Health tab</a></p>'
  + '<p style="margin-top:18px;font-size:12px;color:#6E7477;">Sent by Haggerty App Health Check, only when an app turns red. '
  + 'No email while it stays red. Use Copy for Claude on the Health tab to ask for a fix.</p></div>';
return [{ json: {
  subject: '[Haggerty] ' + (red.length === 1 ? red[0].app + ' turned red' : red.length + ' apps turned red'),
  html
} }];
